"""Build the GdB guide and a blank public shell for private preparation."""
import json,subprocess,hashlib,shutil,re
from pathlib import Path
from html import escape as e
R=Path(__file__).parent
data=json.loads((R/'gdb-data.json').read_text());sources={s['id']:s for s in data['sources']}
base=(R/'template.html').read_text().split('<style>',1)[1].split('</style>',1)[0]
def node(code):return json.loads(subprocess.check_output(['node','-e',code],cwd=R,text=True))
visual=node("const V=require('./care-visuals.js'),G=require('./gdb.js');process.stdout.write(JSON.stringify({icons:Object.fromEntries(['think','calendar','notes','receipt','chat','person','home','move','mood','hand'].map(k=>[k,V.icon(k)])),notice:G.notice,letters:G.letters,svg:G.overlapSVG('getrennt','Hören','Beweglichkeit'),flow:V.flowHTML('gdb'),story:require('./gdb-story.js').scenes.map((s,i)=>({...s,svg:require('./gdb-story.js').image(i)}))}));")
nav=[('./','Pflegegrade & Leistungen'),('./fallbeispiel.html','Fallbeispiel · 100 Fragen'),('./pflegegradrechner.html','Pflegegradrechner'),('./abrechnung.html','Abrechnung & Nachbarschaftshilfe'),('./gdb.html','GdB & Ausweis'),('./meine-vorbereitung.html','Meine Vorbereitung')]
def header(page):return '<header><div class="topbar"><a class="brand" href="./" aria-label="Pflegegrad-Fragen – zur Startseite"><img class="brand-logo" src="./assets/weidenherz-logo.png" width="76" height="76" alt="Zwei Weiden formen ein Herz mit einem handförmigen Busch darin"><span class="brand-text"><span class="brand-name">Pflegegrad-Fragen</span><span class="brand-credit">Erstellt von Andreas und Ricarda</span></span></a><div class="top-actions"><button class="icon-btn" id="large" aria-label="Größere Schrift" aria-pressed="false">A+</button><button class="icon-btn" id="contrast" aria-label="Hohen Kontrast umschalten" aria-pressed="false">◐</button></div></div></header><nav class="section-nav" aria-label="App-Bereiche">'+''.join('<a class="subtle" href="'+url+'"'+(' aria-current="page"' if url=='./'+page else '')+'>'+e(label)+'</a>' for url,label in nav)+'</nav>'
def link(id,label=None):s=sources[id];return '<a class="subtle" href="'+e(s['url'],quote=True)+'" target="_blank" rel="noopener">'+e(label or s['title'])+'</a>'
def src(*ids):return '<p class="gdb-source">Grundlagen: '+''.join('<a href="#quelle-'+id+'">'+e(sources[id]['title'])+'</a> ' for id in ids)+'</p>'
repl={'__BASE_CSS__':base,'__APP_HEADER__':header('gdb.html'),'__CHECKED__':data['checked'],'__GDB_DATA__':json.dumps(data,ensure_ascii=False).replace('</','<\\/'),'__GDB_FLOW__':visual['flow'],
'__THRESHOLDS__':''.join('<article><strong>'+n+'</strong><p>'+t+'</p></article>' for n,t in [('20','Ab hier ist eine GdB-Feststellung vorgesehen.'),('30 / 40','Gleichstellung im Arbeitsleben unter weiteren Voraussetzungen prüfen.'),('50','Ab hier liegt bei den gesetzlichen Voraussetzungen Schwerbehinderung vor.')]),
'__COMPARE_BUTTONS__':''.join('<button class="subtle" id="gdb-vergleich-'+r['id']+'" data-gdb-compare="'+r['id']+'" aria-pressed="'+str(i==0).lower()+'">'+e(r['title'])+'</button>' for i,r in enumerate(data['comparisons'])),
'__COMPARE_SCENE__':e(data['comparisons'][0]['scene']),'__COMPARE_GDB__':e(data['comparisons'][0]['gdb']),'__COMPARE_CARE__':e(data['comparisons'][0]['care']),
'__FORM_FIELDS__':''.join('<article><strong>'+str(i+1)+'</strong><h3>'+e(row[0])+'</h3><p>'+e(row[1])+'</p></article>' for i,row in enumerate(data['formFields'])),
'__DOCUMENTS__':''.join('<article>'+visual['icons']['receipt']+'<h3>'+e(row[0])+'</h3><p>'+e(row[1])+'</p></article>' for row in data['documents']),
'__OVERLAP_BUTTONS__':''.join('<button class="subtle" id="gdb-zusammenspiel-'+r['id']+'" data-gdb-overlap="'+r['id']+'" aria-pressed="'+str(i==0).lower()+'">'+e(r['title'])+'</button>' for i,r in enumerate(data['overlaps'])),
'__OVERLAP_SVG__':visual['svg'],'__OVERLAP_TITLE__':e(data['overlaps'][0]['title']),'__OVERLAP_TEXT__':e(data['overlaps'][0]['explanation']),
'__CASES__':''.join('<article class="gdb-case" id="gdb-fall-'+r['id']+'"><div class="gdb-case-top">'+visual['icons'][r['icon']]+'<div><span class="gdb-label">'+e(r['person'])+'</span><h3>'+e(r['title'])+'</h3></div></div><p>'+e(r['situation'])+'</p><details class="gdb-depth"><summary>Von der allgemeinen Aussage zum konkreten Beispiel</summary><h4>Zu allgemein</h4><blockquote class="vague">'+e(r['vague'])+'</blockquote><h4>Konkretes fiktives Beispiel</h4><blockquote>'+e(r['concrete'])+'</blockquote><h4>Welche Unterlagen könnten das verdeutlichen?</h4><ul>'+''.join('<li>'+e(x)+'</li>' for x in r['evidence'])+'</ul><p>'+e(r['lesson'])+'</p></details></article>' for r in data['cases']),
'__MARKS__':''.join('<details class="gdb-mark" id="gdb-merkzeichen-'+r['id']+'"><summary><strong>'+e(r['id'])+'</strong>'+e(r['title'])+'</summary><p>'+e(r['text'])+'</p><p>'+e(r['next'])+'</p><a href="'+sources['ni-ausweis']['url']+'" target="_blank" rel="noopener">Amtliche Erläuterungen</a></details>' for r in data['marks']),
'__NOTICE_BUTTONS__':''.join('<button type="button" data-gdb-notice="'+str(i)+'" aria-pressed="false"><strong>'+e(row[0])+'</strong>'+e(row[1])+'</button>' for i,row in enumerate(visual['notice']))+'<details><summary>Alle Hinweise zum Lernmuster lesen</summary>'+''.join('<p><strong>'+e(row[0])+':</strong> '+e(row[2])+'</p>' for row in visual['notice'])+'</details>',
'__LETTER_TEMPLATES__':''.join('<article class="gdb-letter"><h3>'+e(row['title'])+'</h3><pre>'+e(row['text'])+'</pre><button class="subtle" type="button" data-copy-gdb="'+str(i)+'">Mustertext kopieren</button><p class="gdb-small" role="status"></p></article>' for i,row in enumerate(visual['letters'])),
'__CONTACTS__':''.join('<article class="gdb-card"><h3>Besuch · '+city+'</h3><address>'+street+'<br>'+postcode+'</address><p>Standorttelefon: <a href="tel:'+phone.replace(' ','')+'">'+phone+'</a></p>'+link(key,'Standort und Besuchsmöglichkeiten prüfen')+'</article>' for city,street,postcode,phone,key in [('Hannover','Schiffgraben 30–32','30175 Hannover','0511 89701-0','hannover'),('Osnabrück','Iburger Str. 30','49082 Osnabrück','0541 5845-1','osnabrueck')]),
'__FAQ__':''.join('<details class="gdb-depth" id="gdb-faq-'+str(i+1)+'"><summary>'+e(row[0])+'</summary><p>'+e(row[1])+'</p>'+(src(row[2]) if row[2] else '')+'</details>' for i,row in enumerate(data['faqs'])),
'__SOURCES__':''.join('<li id="quelle-'+r['id']+'"><a href="'+e(r['url'],quote=True)+'" target="_blank" rel="noopener">'+e(r['title'])+'</a><small>Inhaltlich geprüft: '+data['checked']+'</small></li>' for r in data['sources'])}
story=visual['story']
repl['__PICTURE_STORY__']='<div id="gdbStory" class="gdb-story"><div class="gdb-story-steps" role="group" aria-label="Bild der Geschichte wählen">'+''.join('<button class="subtle" data-story-step="'+str(i)+'" aria-pressed="'+str(i==0).lower()+'" aria-label="Bild '+str(i+1)+': '+e(row['title'])+'">'+str(i+1)+'</button>' for i,row in enumerate(story))+'</div><div class="gdb-story-scene"><div id="gdbStoryImage">'+story[0]['svg']+'</div><article><h3 id="gdbStoryTitle">1 · '+e(story[0]['title'])+'</h3><p id="gdbStoryText">'+e(story[0]['text'])+'</p><p id="gdbStoryTip" class="gdb-note">'+e(story[0]['tip'])+'</p></article></div><div class="gdb-actions"><button class="subtle" id="gdbStoryPrevious" disabled>Vorheriges Bild</button><button class="primary" id="gdbStoryPlay" aria-pressed="false">Bildergeschichte abspielen</button><button class="subtle" id="gdbStoryNext">Nächstes Bild</button></div><p class="gdb-small">Nur auf Wunsch: alle 12 Sekunden ein neues Bild, ein Durchlauf. Jeder Bildschritt kann selbst gewählt und beliebig lange gelesen werden.</p></div>'
repl['__PICTURE_STORY_ALL__']=''.join('<article>'+row['svg']+'<h3>'+str(i+1)+' · '+e(row['title'])+'</h3><p>'+e(row['text'])+'</p><p><strong>Für Ihre Vorbereitung:</strong> '+e(row['tip'])+'</p></article>' for i,row in enumerate(story))
for key,icon in [('THINK','think'),('CALENDAR','calendar'),('NOTES','notes'),('RECEIPT','receipt'),('CHAT','chat'),('PERSON','person'),('HOME','home')]:repl['__ICON_'+key+'__']=visual['icons'][icon]
for key,ids in {'GRUNDLAGEN':['grundlagen','feststellung','pflege'],'ROUTE':['ni-verfahren','ni-faq','widerspruch'],'ANTRAG':['ni-online','ni-formulare'],'UNTERLAGEN':['ni-verfahren'],'GESAMT':['versmedv'],'MARKS':['ni-ausweis','gleichstellung'],'BESCHEID':['widerspruch','akte','ni-faq']}.items():repl['__SRC_'+key+'__']=src(*ids)
for key,id,label in [('ONLINE','ni-online','Offizielle Online-Anträge öffnen'),('FORMULAR','ni-formulare','Amtliche Formulare und Merkblätter öffnen'),('GLEICH','gleichstellung','Gleichstellung bei der Arbeitsagentur'),('NACHTEILE','nachteile','Offizielle Nachteilsausgleiche ansehen'),('POST','ni-formulare','Quelle der zentralen Postanschrift'),('ORT','ortsverzeichnis','Zuständige Stelle nach Wohnort suchen')]:repl['__LINK_'+key+'__']=link(id,label)
html=(R/'gdb-template.html').read_text()
for k,v in repl.items():html=html.replace(k,v)
assert not re.search(r'__[A-Z_]+__',html)
plans=[{'id':'gdb','title':'GdB-Antrag vorbereiten','tasks':['Anlass und zuständige Stelle klären','Behandelnde Stellen und Berichte zusammentragen','Eigene Alltagsbeispiele formulieren','Amtlichen Antrag vollständig prüfen','Tatsächlich eingereichte Unterlagen und Eingang dokumentieren'],'documents':[r[0] for r in data['documents']]},
{'id':'pflege','title':'Pflegegrad-Antrag vorbereiten','tasks':['Antrag bei der eigenen Pflegekasse anstoßen','Alltag und tatsächlich benötigte Hilfe notieren','Unterlagen für die Begutachtung bereitlegen','Fragen und mögliche Begleitung abstimmen','Bescheid und Gutachten nach Erhalt prüfen'],'documents':['Aktuelle Befunde und Berichte','Medikamentenübersicht','Alltagsnotizen oder Pflegetagebuch','Vorhandener Pflegegradbescheid','Vertretungsnachweis, falls erforderlich']},
{'id':'abrechnung','title':'Pflegeleistung abrechnen','tasks':['Passende Leistung und verfügbares Budget mit der Pflegekasse klären','Anbieter und Zahlungsweg abstimmen','Leistungsnachweise und Rechnung prüfen','Unterlagen beim passenden Kassenweg einreichen','Kopie und Eingang behalten; Erstattung abgleichen'],'documents':['Rechnung oder Abrechnungsbogen','Leistungsnachweis mit tatsächlichen Einsätzen','Zahlungsnachweis, falls erforderlich','Anerkennungs- oder Qualifikationsnachweis, falls erforderlich','Abtretung, falls vereinbart']},
{'id':'bescheid','title':'Bescheid nachvollziehen und prüfen','tasks':['Originalbescheid und Rechtsbehelfsbelehrung lesen','Bekanntgabe und maßgebliche Frist selbst prüfen beziehungsweise beraten lassen','Berücksichtigte Unterlagen mit eigener Übersicht vergleichen','Offene Punkte konkret notieren; bei Bedarf Akteneinsicht anfragen','Passenden nächsten Schritt rechtzeitig in zulässiger Form veranlassen'],'documents':['Vollständiger Originalbescheid','Eigene Kopie des Antrags','Eingereichte Berichte und Anlagen','Zustellungs- oder Zugangsinformationen','Nachweis eines tatsächlich eingelegten Rechtsbehelfs, falls vorhanden']}]
(R/'preparation-plans.json').write_text(json.dumps(plans,ensure_ascii=False,indent=2)+'\n')
workspace=(R/'workspace-template.html').read_text().replace('__BASE_CSS__',base).replace('__APP_HEADER__',header('meine-vorbereitung.html')).replace('__WORKSPACE_PLANS__',json.dumps(plans,ensure_ascii=False).replace('</','<\\/'))
for name,content in [('gdb.html',html),('meine-vorbereitung.html',workspace)]:
 for asset in ['gdb.css','gdb.js','gdb-story.js','workspace.css','workspace.js']:
  digest=hashlib.sha256((R/asset).read_bytes()).hexdigest()[:12];content=content.replace('./'+asset+'"','./'+asset+'?v='+digest+'"')
 (R/name).write_text(content);(R/'dist'/name).write_text(content)
for asset in ['gdb.css','gdb.js','gdb-story.js','workspace.css','workspace.js','assets/gdb-wegweiser.svg']:shutil.copy2(R/asset,R/'dist'/asset)
print('GdB Niedersachsen: bebilderter Leitfaden, vier erfundene Fälle, acht Merkzeichen, persönliche Aufgaben- und Unterlagenübersicht erstellt.')
